            original = original.replace(old_text, new_text, 1)
        path.write_text(original)
    elif header.startswith('*** Add File: '):
        path = pathlib.Path(header[len('*** Add File: '):])
        i += 1
        content = []
        while i < len(lines) - 1 and not lines[i].startswith('*** '):
