        super(
            method,
            annotations,
            existingVariables,
            parameterAssignment,
            factoryMethod,
            mapNullToDefault,
            loopVariableName,
            beforeMappingReferences,
            afterMappingReferences,
            selectionParameters,
            sourceParameterPresenceCheck
        );
        this.entryMappingType = entryMappingType;
    }

    private final Type entryMappingType;

    @Override
    public Set<Type> getImportTypes() {
        Set<Type> types = super.getImportTypes();

        types.add( getSourceElementType() );
        return types;
    }

    public Type getSourceElementType() {
        Type sourceParameterType = getSourceParameter().getType();

        if ( sourceParameterType.isArrayType() ) {
            return sourceParameterType.getComponentType();
        }
        else if ( sourceParameterType.isMapType() ) {
            return getMapEntryType( sourceParameterType );
        }
        else {
            return first( sourceParameterType.determineTypeArguments( Iterable.class ) ).getTypeBound();
        }
    }

    @Override
    public Type getResultElementType() {
        if ( getResultType().isArrayType() ) {
            return getResultType().getComponentType();
        }
        else if ( getResultType().isMapType() ) {
            return getMapEntryType( getResultType() );
        }
        else {
            return first( getResultType().determineTypeArguments( Iterable.class ) );
        }
    }

    public boolean isSourceMap() {
        return getSourceParameter().getType().isMapType();
    }

    public boolean isResultMap() {
        return getResultType().isMapType();
    }

    public Type getEntryMappingType() {
        return entryMappingType;
    }

    private Type getMapEntryType(Type mapType) {
        return mapType.getTypeFactory().getMapEntryType( mapType.determineTypeArguments( Map.class ) );
    }
